"""Human-readable Guard operations dashboard shell."""

GUARD_OPERATIONS_PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Guard operations</title>
<style>
:root{font-family:system-ui,-apple-system,sans-serif;color:#17202a;background:#f4f6f8}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1500px;margin:auto;padding:24px}.muted{color:#65727e;font-size:.88rem}.filters,.summary,.card{background:#fff;border:1px solid #dfe5ea;border-radius:12px;padding:14px;margin-bottom:14px}.filters{display:flex;gap:8px;flex-wrap:wrap;align-items:center}input,select,button{font:inherit;padding:8px;border:1px solid #c7d0d9;border-radius:7px;background:#fff}button{cursor:pointer}.primary{background:#1768cf;color:#fff;border-color:#1768cf}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:10px}.metric{padding:8px 10px;border-left:3px solid #1768cf;background:#f7f9fb;border-radius:6px}.metric strong{display:block;font-size:1.5rem}.metric span{font-size:.78rem;color:#65727e}.card h2{margin:0 0 4px;font-size:1.1rem}.chips{display:flex;gap:5px;flex-wrap:wrap}.pill{display:inline-block;border-radius:12px;padding:3px 8px;background:#e8eef5;margin:2px;font-size:.8rem}.pill.group{background:#eee7ff;color:#5a32a3}.pill.private{background:#e4f5ec;color:#176b43}.pill.alert{background:#ffe5e5;color:#a62d45}.pill.ok{background:#e4f5ec;color:#176b43}.pill.fail{background:#ffe5e5;color:#a62d45}.row{margin-top:10px}.grid{display:grid;grid-template-columns:minmax(270px,.8fr) minmax(500px,2fr);gap:16px}.timeline{border-left:2px solid #dfe5ea;margin:12px 0 0 5px;padding-left:14px}.event{position:relative;margin:0 0 12px}.event:before{content:"";position:absolute;left:-21px;top:6px;width:8px;height:8px;border-radius:50%;background:#1768cf}.event-title{font-weight:700}.event-meta{font-size:.75rem;color:#65727e}.event-detail{font-size:.86rem;margin-top:2px;white-space:pre-wrap}.analysis{border-top:1px solid #e5e9ed;padding:12px 0}.analysis:first-child{border-top:0}.analysis h3{margin:0 0 5px;font-size:1rem}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.box{background:#f7f9fb;border-radius:8px;padding:9px}.box h4{margin:0 0 5px;font-size:.78rem;color:#65727e;text-transform:uppercase;letter-spacing:.04em}.evidence{margin:6px 0;padding:8px;background:#fff;border-left:3px solid #1768cf;white-space:pre-wrap}.error{color:#a62d45}.empty{padding:30px;text-align:center}.refresh{margin-left:auto}@media(max-width:850px){.grid{grid-template-columns:1fr}.two{grid-template-columns:1fr}.wrap{padding:12px}}
</style></head><body><main class="wrap"><header><h1>Guard operations</h1><div id="status" class="muted">Loading…</div></header>
<form class="filters" onsubmit="load(event)"><select id="mode"><option value="">all chats</option><option value="private">private</option><option value="group">groups</option></select><select id="decision"><option value="">all decisions</option><option>none</option><option>watch</option><option>concerning</option><option>urgent</option></select><input id="category" placeholder="category"><input id="chat" placeholder="chat id"><label><input id="overdue" type="checkbox"> overdue only</label><input id="from" type="date"><input id="to" type="date"><button class="primary">Filter</button><button type="button" class="refresh" onclick="load()">Refresh</button></form>
<section id="summary" class="summary"></section><section id="results"></section></main>
<script>
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const fmt=v=>v?new Date(v).toLocaleString(): '—';
const duration=(a,b)=>a&&b?Math.round((new Date(b)-new Date(a))/1000)+'s':'—';
async function load(e){if(e)e.preventDefault();const p=new URLSearchParams();for(const [id,key] of [['mode','mode'],['decision','decision'],['category','category'],['chat','chat_id'],['from','date_from'],['to','date_to']]){const v=document.getElementById(id).value;if(v)p.set(key,v)}if(document.getElementById('overdue').checked)p.set('overdue','true');const r=await fetch('/api/debug/guard/operations?'+p);if(r.status===401){location.href='/q/expired';return}if(!r.ok){document.getElementById('status').textContent='Error '+r.status;return}render(await r.json())}
function render(data){const s=data.summary;document.getElementById('status').textContent='Updated '+fmt(data.generated_at)+' · '+s.monitored_chats+' monitored chats';document.getElementById('summary').innerHTML=[['monitored_chats','Monitored'],['private_chats','Private'],['group_chats','Groups'],['analyzed_chats','Analyzed'],['pending_chats','Pending'],['overdue_chats','Overdue'],['analyzer_failures','Analyzer failures'],['alerts','Alerts'],['delivery_failures','Delivery failures']].map(([k,l])=>`<div class="metric"><strong>${esc(s[k])}</strong><span>${l}</span></div>`).join('');document.getElementById('results').innerHTML=data.chats.map(renderChat).join('')||'<div class="card empty">No Guard chats match these filters.</div>'}
function renderChat(x){const mode=x.is_group?'group':'private';const d=x.latest_analysis;const p=x.latest_policy;const dl=x.latest_delivery;return `<article class="card"><h2>${esc(x.chat_name)} <span class="pill ${mode}">${mode}</span> <span class="pill">${esc(x.last_decision)}</span>${dl&&dl.action_status==='succeeded'?'<span class="pill ok">delivered</span>':''}</h2><div class="muted">${esc(x.chat_id)} · child ${esc(x.child_user_id)} · last message ${fmt(x.last_message_at)}</div><div class="row"><b>Queue:</b> activity v${x.activity_version}, analyzed v${x.last_analyzed_version}, backlog ${x.backlog}, ${x.overdue?'<span class="pill fail">overdue</span>':'on schedule'}<br><span class="muted">pending ${fmt(x.pending_since)} · next ${fmt(x.next_analysis_at)} · ${esc(x.next_analysis_reason||'no pending reason')}</span></div><div class="row"><b>Latest policy:</b> ${p?`<span class="pill ${p.reason==='not_actionable'?'ok':p.reason==='policy_suppressed'?'alert':''}">${esc(p.reason)}</span> ${esc(p.detail)}`:'not evaluated'}</div><div class="row"><b>Delivery:</b> ${dl?`${esc(dl.action_status||dl.alert_status)} · ${esc(dl.reason)}${dl.error?' · '+esc(dl.error):''}`:'no alert for latest result'}</div><div class="row"><b>Threshold episodes:</b> ${x.threshold_states.length?x.threshold_states.map(t=>`<span class="pill">${esc(t.threshold_family)} · ${esc(t.status)}${t.current_kind?' · '+esc(t.current_kind):''}</span>`).join(''):'none recorded'}</div><div class="grid"><section><h3>Decision timeline</h3><div class="timeline">${x.timeline.map(renderEvent).join('')||'<span class="muted">No events yet</span>'}</div></section><section><h3>Analysis history</h3>${x.analyses.map(renderAnalysis).join('')||'<span class="muted">No analysis has committed yet.</span>'}</section></div></article>`}
function renderEvent(e){return `<div class="event"><div class="event-title">${esc(e.title)} <span class="pill">${esc(e.status||'')}</span></div><div class="event-meta">${fmt(e.at)}${e.target_version?' · version '+e.target_version:''}</div><div class="event-detail">${esc(e.detail||'')}</div></div>`}
function renderAnalysis(a){const gold=a.gold_scenario_id?`<a href="/demo/guard?scenario_id=${encodeURIComponent(a.gold_scenario_id)}">Open Gold / Live Compare</a>`:'';return `<div class="analysis"><h3>${fmt(a.created_at)} · ${esc(a.decision)} · confidence ${a.confidence}</h3><div class="muted">version ${a.target_version} · ${esc(a.model)} · prompt ${esc(a.prompt_version)} · analyzer ${esc(a.analyzer_version)} · taxonomy ${esc(a.taxonomy_version)}</div><div class="row"><b>Categories:</b> ${chips(a.categories)}<br><b>Signals:</b> ${chips(a.signals)}<br><b>Cumulative:</b> ${chips(a.cumulative_signals)}</div><div class="row"><b>Reason:</b> ${esc(a.reason)}</div><div class="two row"><div class="box"><h4>Participants</h4>${participantText(a)}</div><div class="box"><h4>Policy and delivery</h4>${policyText(a)}${a.delivery?`<br>${deliveryText(a.delivery)}`:'No alert created'}</div></div><details class="row"><summary>Evidence (${a.evidence_message_ids.length})${gold?' · '+gold:''}</summary>${a.evidence_messages.map(m=>`<div class="evidence"><b>${esc(m.direction)} · ${esc(m.sender||'unknown')} · ${fmt(m.timestamp)}</b><br>${esc(m.text)}</div>`).join('')||'<span class="muted">Evidence messages are unavailable.</span>'}</details></div>`}
function chips(v){return v&&v.length?v.map(x=>`<span class="pill">${esc(x)}</span>`).join(''):'<span class="muted">none</span>'}
function participantText(a){const roles=a.participant_diagnostics||[];const impact=a.participant_impact||[];return (roles.length?roles.map(p=>`<div>${esc(p.display_name||p.canonical_id||'unknown')} · ${esc(p.role||'unknown')}</div>`).join(''):'<div class="muted">No participant diagnostics</div>')+(impact.length?`<details><summary>Impact roles</summary><pre>${esc(JSON.stringify(impact,null,2))}</pre></details>`:'<div class="muted">Child actor/target role: unknown</div>')}
function policyText(p){return p?`<span class="pill">${esc(p.reason)}</span> ${esc(p.detail)}<br><span class="muted">${esc(p.outcome)} · ${fmt(p.evaluated_at)}</span>`:'not evaluated'}
function deliveryText(d){return `<span class="pill ${d.action_status==='failed'||d.action_status==='indeterminate'?'fail':''}">${esc(d.action_status||d.alert_status)}</span> ${esc(d.reason)}${d.result_present?' · provider result recorded':''}`}
load();
</script></body></html>'''
